    def union(x, y):
        rootX = find_root(x)
        rootY = find_root(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    def find_distance(a, b, sizes):
        path_length = 0
        while a != b:
            if a > b:
                a, b = b, a
            if a == 1:
                path_length += 1
                a = sizes[find_root(b)] + 1
            else:
                path_length += 1
                a = sizes[find_root(a - 1)] + 1
        return path_length

